INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('welcome', '<tg-emoji emoji-id="5310228579009699834">🎉</tg-emoji> <b>سلام، به آکادمی بهرام خوش آمدید!</b>\n\nاینجا می‌توانید دوره‌ها را ببینید، ثبت‌نام کنید و با پشتیبانی در ارتباط باشید.\nاز منوی پایین شروع کنید <tg-emoji emoji-id="5418085807791545980">🔝</tg-emoji>', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('main_menu_hint', '<tg-emoji emoji-id="5312486108309757006">🏠</tg-emoji> <b>منوی آکادمی بهرام</b>\n\n<tg-emoji emoji-id="5357419403325481346">🎓</tg-emoji> دوره‌ها\n<tg-emoji emoji-id="5382003830487523366">🎤</tg-emoji> سمینارها\n<tg-emoji emoji-id="5309984423003823246">📣</tg-emoji> سات\n<tg-emoji emoji-id="5377624166436445368">🎟</tg-emoji> پشتیبانی\n\nهر بخش را از دکمه‌های پایین انتخاب کنید <tg-emoji emoji-id="5312241539987020022">🔥</tg-emoji>', '2026-07-26 21:20:41');
