INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('registration_ask_mobile', '<tg-emoji emoji-id="5409357944619802453">📱</tg-emoji> <b>تأیید شماره موبایل</b>\n\nبرای ادامه ثبت‌نام، شماره ایران خود را بفرستید.\n\n<tg-emoji emoji-id="5418085807791545980">🔝</tg-emoji> فقط از دکمه <b>ارسال شماره تماس</b> استفاده کنید.', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('registration_ask_name', '<tg-emoji emoji-id="5238156910363950406">✍️</tg-emoji> <b>نام و نام خانوادگی</b>\n\nلطفاً نام کامل خود را بنویسید.\n<tg-emoji emoji-id="5237699328843200968">✅</tg-emoji> فقط حروف فارسی یا انگلیسی (۲ تا ۶۰ کاراکتر).', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('registration_complete', '<tg-emoji emoji-id="5237699328843200968">✅</tg-emoji> <b>ثبت‌نام شما انجام شد</b>\n\nبه جمع آکادمی خوش آمدید <tg-emoji emoji-id="5310228579009699834">🎉</tg-emoji>\nمنوی پایین همیشه در دسترس است.', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('purchase_need_course', '<tg-emoji emoji-id="5418115271267197333">🪪</tg-emoji> <b>دسترسی محدود</b>\n\nبرای ورود به این بخش باید یکی از دوره‌ها را تهیه کنید.\nاز دکمه <b>دوره‌ها</b> در منو می‌توانید ادامه دهید.', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('purchase_catalog_empty', '<tg-emoji emoji-id="5357315181649076022">📁</tg-emoji> <b>هنوز دوره‌ای فعال نیست</b>\n\nبه‌زودی دوره‌های جدید اضافه می‌شوند. از پشتیبانی هم می‌توانید بپرسید.', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('courses_catalog_intro', '<tg-emoji emoji-id="5357419403325481346">🎓</tg-emoji> <b>دوره‌های فعال آکادمی</b>\n\nبنر هر دوره را ببینید، جزئیات را بخوانید و با یک ضربه خرید کنید <tg-emoji emoji-id="5312241539987020022">🔥</tg-emoji>', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('seminars_catalog_intro', '<tg-emoji emoji-id="5382003830487523366">🎤</tg-emoji> <b>سمینارهای پیش‌رو</b>\n\nزمان، مکان و ظرفیت را ببینید و ثبت‌نام کنید <tg-emoji emoji-id="5348436127038579546">✈️</tg-emoji>', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('seminars_catalog_empty', '<tg-emoji emoji-id="5357315181649076022">📁</tg-emoji> <b>سمیناری برای نمایش نیست</b>\n\nفعلاً سمینار فعالی نداریم. به‌زودی رویدادهای جدید اینجا می‌آید.', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('support_prompt', '<tg-emoji emoji-id="5377624166436445368">🎟</tg-emoji> <b>پشتیبانی آکادمی</b>\n\nموضوع را انتخاب کنید، بعد پیامتان را بفرستید — ما سریع پیگیری می‌کنیم.', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('support_message_received', '<tg-emoji emoji-id="5237699328843200968">✅</tg-emoji> <b>پیام شما ثبت شد</b>\n\nبه‌زودی پاسخ می‌دهیم. ممنون از صبر شما <tg-emoji emoji-id="5312138559556164615">❤️</tg-emoji>', '2026-07-26 21:20:41');
