INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('error_forced_join', '<tg-emoji emoji-id="5309984423003823246">📣</tg-emoji> <b>عضویت الزامی</b>\n\nبرای ادامه باید در کانال/گروه‌های اعلام‌شده عضو شوید.', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('error_payment_failed', '<tg-emoji emoji-id="5377498341074542641">‼️</tg-emoji> <b>پرداخت ناموفق بود</b>\n\nدوباره تلاش کنید یا از پشتیبانی کمک بگیرید.', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('error_generic', '<tg-emoji emoji-id="5379748062124056162">❗️</tg-emoji> <b>مشکلی پیش آمد</b>\n\nلطفاً دوباره تلاش کنید. اگر ادامه داشت، پشتیبانی در دسترس است.', '2026-07-26 21:20:41');
INSERT INTO bot_messages (message_key, body, updated_at) VALUES ('iran_server_unreachable', '<tg-emoji emoji-id="5379748062124056162">❗️</tg-emoji> <b>اتصال به سرور اصلی برقرار نشد.</b>\n\nلطفاً حدود یک ساعت دیگر دوباره تلاش کنید.\nمنو و اطلاعات ذخیره‌شده روی همین ربات همچنان در دسترس است.', '2026-07-26 21:20:41');
